import json
import os
import logging
from dataclasses import dataclass, field

logger = logging.getLogger(__name__)


@dataclass
class Interface:
    name: str
    vlan: int | None = None
    enabled: bool = True
    description: str = ""
    tagged: list[int] = field(default_factory=list)


def parse_vlan_list(spec: str) -> list[int]:
    vlans = []
    parts = spec.split()
    i = 0
    while i < len(parts):
        if i + 2 < len(parts) and parts[i + 1] == "to":
            start, end = int(parts[i]), int(parts[i + 2])
            logger.info("range", start, end)
            vlans.extend(range(start, end + 1))
            i += 3
        else:
            logger.info("single", parts[i])
            vlans.append(int(parts[i]))
            i += 1
    return vlans


